import{_ as a,o as t,c as r,an as i}from"./chunks/framework.DHjvKR4f.js";const u=JSON.parse('{"title":"EpiAwareADTools","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function s(n,e,l,p,h,d){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="EpiAwareADTools" tabindex="-1">EpiAwareADTools <a class="header-anchor" href="#EpiAwareADTools" aria-label="Permalink to &quot;EpiAwareADTools {#EpiAwareADTools}&quot;">​</a></h1><p>Automatic-differentiation safety machinery for the EpiAware modelling stack.</p><h2 id="Why-EpiAwareADTools?" tabindex="-1">Why EpiAwareADTools? <a class="header-anchor" href="#Why-EpiAwareADTools?" aria-label="Permalink to &quot;Why EpiAwareADTools? {#Why-EpiAwareADTools?}&quot;">​</a></h2><p>EpiAwareADTools is the EpiAware org&#39;s shared home for AD-safety machinery and AD workarounds. It is deliberately framed as fixes we host while we try to fix things upstream: every entry is documented with the upstream package or issue where it ideally belongs, and each is deleted once that upstream fix lands.</p><p>Three families make up the current surface.</p><ul><li><p>The tape-strip pair <code>primal</code> and <code>primal_distribution</code> reduce an AD-wrapped scalar or distribution to its underlying primal, keeping a non-differentiable hyperparameter (an integration window, a clamp location) off the AD path on every backend.</p></li><li><p>The AD-safe evaluation hooks (<code>cdf_ad_safe</code>, <code>logcdf_ad_safe</code>, <code>ccdf_ad_safe</code>, <code>logccdf_ad_safe</code>, and <code>pdf_ad_safe</code>) let a wrapper package overload CDF evaluation for its own component types, backed by analytic <code>Gamma</code> and <code>Beta</code> CDF derivatives that <code>SpecialFunctions</code> leaves unimplemented.</p></li><li><p>Correct upstream <code>ChainRulesCore</code> rules lifted into a backend that lacks them, currently <code>LogExpFunctions.xlogy</code>/<code>xlog1py</code> under Mooncake, which otherwise returns a wrong shape-gradient for any Gamma log-density differentiated at <code>shape == 1</code>.</p></li></ul><p>Per-backend behaviour for ForwardDiff, ReverseDiff, Enzyme, Mooncake, and ChainRulesCore is supplied by package extensions loaded when each backend is present.</p><h2 id="Getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#Getting-started" aria-label="Permalink to &quot;Getting started {#Getting-started}&quot;">​</a></h2><p>See the <a href="https://epiawareadtools.epiaware.org/stable/" target="_blank" rel="noreferrer">documentation</a> for a full walkthrough.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EpiAwareADTools, Distributions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># AD-safe Gamma CDF, differentiable in shape/scale on every supported backend.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cdf_ad_safe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Gamma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Strip an AD wrapper back to its primal value.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">primal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">3.0</span></span></code></pre></div><h2 id="Related-packages" tabindex="-1">Related packages <a class="header-anchor" href="#Related-packages" aria-label="Permalink to &quot;Related packages {#Related-packages}&quot;">​</a></h2><ul><li><p><a href="https://convolveddistributions.epiaware.org/dev/" target="_blank" rel="noreferrer">ConvolvedDistributions.jl</a>, <a href="https://composeddistributions.epiaware.org/dev/" target="_blank" rel="noreferrer">ComposedDistributions.jl</a>, <a href="https://modifieddistributions.epiaware.org/dev/" target="_blank" rel="noreferrer">ModifiedDistributions.jl</a>, <a href="https://lowereddistributions.epiaware.org/dev/" target="_blank" rel="noreferrer">LoweredDistributions.jl</a> and <a href="https://censoreddistributions.epiaware.org/stable/" target="_blank" rel="noreferrer">CensoredDistributions.jl</a> import these AD-safe hooks in their own source and overload them for their component types, so their densities differentiate on every supported backend.</p></li><li><p><a href="https://github.com/EpiAware/DistributionsInference.jl" target="_blank" rel="noreferrer">DistributionsInference.jl</a> is the emerging fit-protocol layer across those packages, where the AD-safety this package provides is what makes gradient-based fitting work.</p></li></ul><h2 id="Where-to-learn-more" tabindex="-1">Where to learn more <a class="header-anchor" href="#Where-to-learn-more" aria-label="Permalink to &quot;Where to learn more {#Where-to-learn-more}&quot;">​</a></h2><ul><li><p>Want to get started running code? Check out the <a href="https://epiawareadtools.epiaware.org/stable/getting-started/" target="_blank" rel="noreferrer">Getting started documentation</a>.</p></li><li><p>Want to understand the API? Check out our <a href="https://epiawareadtools.epiaware.org/stable/lib/public" target="_blank" rel="noreferrer">API reference</a>.</p></li><li><p>Want to contribute to <code>EpiAwareADTools</code>? Check the <a href="https://github.com/EpiAware/EpiAwareADTools.jl/issues" target="_blank" rel="noreferrer">open issues</a> and the Contributing section below.</p></li><li><p>Want to see our code? Check out our <a href="https://github.com/EpiAware/EpiAwareADTools.jl" target="_blank" rel="noreferrer">GitHub Repository</a>.</p></li></ul><h2 id="Getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#Getting-help" aria-label="Permalink to &quot;Getting help {#Getting-help}&quot;">​</a></h2><p>For usage questions, ask on the <a href="https://discourse.julialang.org" target="_blank" rel="noreferrer">Julia Discourse</a> (the SciML or usage categories) or the <a href="https://community.epinowcast.org" target="_blank" rel="noreferrer">epinowcast community forum</a>, our home for epidemiological modelling questions. Please use <a href="https://github.com/EpiAware/EpiAwareADTools.jl/issues" target="_blank" rel="noreferrer">GitHub issues</a> for bug reports and feature requests only.</p><h2 id="Part-of-the-EpiAware-ecosystem" tabindex="-1">Part of the EpiAware ecosystem <a class="header-anchor" href="#Part-of-the-EpiAware-ecosystem" aria-label="Permalink to &quot;Part of the EpiAware ecosystem {#Part-of-the-EpiAware-ecosystem}&quot;">​</a></h2><p>EpiAwareADTools is part of <a href="https://epiaware.org" target="_blank" rel="noreferrer">EpiAware</a>, a set of composable tools for infectious disease modelling. See the <a href="https://github.com/EpiAware" target="_blank" rel="noreferrer">other packages</a> in the ecosystem.</p><h2 id="Contributing" tabindex="-1">Contributing <a class="header-anchor" href="#Contributing" aria-label="Permalink to &quot;Contributing {#Contributing}&quot;">​</a></h2><p>We welcome contributions and new contributors! Please open an issue or pull request on <a href="https://github.com/EpiAware/EpiAwareADTools.jl" target="_blank" rel="noreferrer">GitHub</a>. This package follows <a href="https://github.com/SciML/ColPrac" target="_blank" rel="noreferrer">ColPrac</a> and is formatted with <a href="https://github.com/fredrikekre/Runic.jl" target="_blank" rel="noreferrer">Runic</a>.</p><h2 id="How-to-cite" tabindex="-1">How to cite <a class="header-anchor" href="#How-to-cite" aria-label="Permalink to &quot;How to cite {#How-to-cite}&quot;">​</a></h2><p>If you use EpiAwareADTools in your work, please cite it. Citation metadata lives in <a href="https://github.com/EpiAware/EpiAwareADTools.jl/blob/main/CITATION.cff" target="_blank" rel="noreferrer"><code>CITATION.cff</code></a>, which GitHub renders as a &quot;Cite this repository&quot; button on the repository page.</p><h2 id="Code-of-conduct" tabindex="-1">Code of conduct <a class="header-anchor" href="#Code-of-conduct" aria-label="Permalink to &quot;Code of conduct {#Code-of-conduct}&quot;">​</a></h2><p>Please note that the EpiAwareADTools project is released with a <a href="https://github.com/EpiAware/.github/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Contributor Code of Conduct</a>. By contributing, you agree to abide by its terms.</p>`,25)])])}const f=a(o,[["render",s]]);export{u as __pageData,f as default};
